{"path":"dev-workflow.js","content":"#!/usr/bin/env node

/**
 * 完整开发流程自动化工具
 * Prompt输入需求 -> 开发 -> 错误检查 -> 测试 -> 确认提交
 */

const { execSync, spawn } = require('child_process');
const fs = require('fs');
const path = require('path');
const readline = require('readline');

class DevWorkflow {
  constructor() {
    this.stages = [
      '需求输入',
      '开发实现',
      '错误检查',
      '测试验证',
      '确认提交'
    ];
    this.currentStage = 0;
    this.workflowData = {
      requirement: '',
      filesChanged: [],
      errors: [],
      testResults: null,
      commitMessage: ''
    };
  }

  /**
   * 阶段 1: 需求输入
   */
  async inputRequirement() {
    console.log('\n📝 阶段 1: 需求输入');
    console.log('='.repeat(50));

    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });

    return new Promise((resolve) => {
      rl.question('请描述您的需求（支持多行，输入空行结束）:\n', (firstLine) => {
        let requirement = firstLine;

        const askNextLine = () => {
          rl.question('', (line) => {
            if (line.trim() === '') {
              this.workflowData.requirement = requirement;
              console.log('\n✅ 需求已记录:');
              console.log('-'.repeat(50));
              console.log(requirement);
              console.log('-'.repeat(50));
              rl.close();
              resolve();
            } else {
              requirement += '\n' + line;
              askNextLine();
            }
          });
        };

        if (firstLine.trim() !== '') {
          askNextLine();
        } else {
          console.log('❌ 需求不能为空！');
          rl.close();
          process.exit(1);
        }
      });
    });
  }

  /**
   * 阶段 2: 开发实现
   */
  async develop() {
    console.log('\n🔧 阶段 2: 开发实现');
    console.log('='.repeat(50));

    console.log('需求分析:');
    console.log(this.workflowData.requirement);
    console.log('\n开始开发...\n');

    // 这里可以集成 AI 代码生成
    // 示例：根据需求自动生成代码
    try {
      // 检查项目结构
      const srcPath = path.join(__dirname, 'src');
      if (fs.existsSync(srcPath)) {
        console.log('✅ 找到 src 目录');

        // 示例：创建一个基于需求的新组件
        const componentName = this.extractComponentName(this.workflowData.requirement);
        if (componentName) {
          console.log(`📦 检测到需要创建组件: ${componentName}`);
          // 这里可以调用代码生成逻辑
        }
      }

      // 运行编译检查
      console.log('\n🔍 执行初始编译检查...');
      const compileResult = this.runCompileCheck();

      if (compileResult.success) {
        console.log('✅ 初始编译检查通过');
      } else {
        console.log('⚠️  初始编译检查发现问题:');
        console.log(compileResult.output);
      }

      this.currentStage = 1;
      return true;
    } catch (error) {
      console.error('❌ 开发阶段出错:', error.message);
      return false;
    }
  }

  /**
   * 阶段 3: 错误检查
   */
  async checkErrors() {
    console.log('\n🔍 阶段 3: 错误检查');
    console.log('='.repeat(50));

    const checks = [
      { name: 'TypeScript 类型检查', cmd: 'npm run compile-check-ts-native' },
      { name: 'ESLint 代码规范检查', cmd: 'npm run eslint' },
      { name: '代码格式检查', cmd: 'npm run hygiene' }
    ];

    let allPassed = true;

    for (const check of checks) {
      console.log(`\n正在执行: ${check.name}`);
      console.log('-'.repeat(50));

      try {
        const output = execSync(check.cmd, { 
          encoding: 'utf8',
          stdio: 'pipe',
          timeout: 120000 // 2分钟超时
        });
        console.log(`✅ ${check.name} 通过`);
      } catch (error) {
        console.log(`❌ ${check.name} 失败`);
        console.log('错误信息:');
        console.log(error.stdout || error.stderr || error.message);
        this.workflowData.errors.push({
          stage: check.name,
          error: error.stdout || error.stderr || error.message
        });
        allPassed = false;

        // 询问是否继续
        const rl = readline.createInterface({
          input: process.stdin,
          output: process.stdout
        });

        const answer = await new Promise(resolve => {
          rl.question('\n是否要查看详细错误并修复？(y/n): ', resolve);
        });
        rl.close();

        if (answer.toLowerCase() === 'y') {
          console.log('\n请手动修复错误后按回车继续...');
          await new Promise(resolve => {
            const r = readline.createInterface({
              input: process.stdin,
              output: process.stdout
            });
            r.question('', () => {
              r.close();
              resolve();
            });
          });
        }
      }
    }

    if (allPassed) {
      console.log('\n✅ 所有错误检查通过！');
      return true;
    } else {
      console.log('\n⚠️  部分检查未通过，请修复后重新运行');
      return false;
    }
  }

  /**
   * 阶段 4: 测试验证
   */
  async runTests() {
    console.log('\n🧪 阶段 4: 测试验证');
    console.log('='.repeat(50));

    const testTypes = [
      { name: '单元测试', cmd: 'npm test -- --watchAll=false', optional: false },
      { name: '集成测试', cmd: 'npm run test-browser-no-install', optional: true },
      { name: 'E2E 测试', cmd: 'npm run test-extension', optional: true }
    ];

    for (const test of testTypes) {
      console.log(`\n正在执行: ${test.name}`);
      console.log('-'.repeat(50));

      try {
        const output = execSync(test.cmd, { 
          encoding: 'utf8',
          stdio: 'pipe',
          timeout: 300000 // 5分钟超时
        });
        console.log(`✅ ${test.name} 通过`);
        this.workflowData.testResults = 'passed';
      } catch (error) {
        if (test.optional) {
          console.log(`⚠️  ${test.name} 失败（可选测试）`);
          console.log('错误:', error.stdout || error.stderr || error.message);
        } else {
          console.log(`❌ ${test.name} 失败`);
          console.log('错误:', error.stdout || error.stderr || error.message);
          this.workflowData.testResults = 'failed';

          const rl = readline.createInterface({
            input: process.stdin,
            output: process.stdout
          });

          const answer = await new Promise(resolve => {
            rl.question('\n测试失败，是否继续？(y/n): ', resolve);
          });
          rl.close();

          if (answer.toLowerCase() !== 'y') {
            return false;
          }
        }
      }
    }

    console.log('\n✅ 测试阶段完成');
    return true;
  }

  /**
   * 阶段 5: 确认提交
   */
  async confirmAndCommit() {
    console.log('\n✅ 阶段 5: 确认提交');
    console.log('='.repeat(50));

    // 检查 Git 状态
    console.log('\n📊 Git 状态:');
    try {
      const status = execSync('git status --short', { encoding: 'utf8' });
      if (!status.trim()) {
        console.log('❌ 没有检测到任何更改');
        return false;
      }
      console.log(status);
    } catch (error) {
      console.error('❌ 无法获取 Git 状态');
      return false;
    }

    // 生成提交信息
    const defaultCommitMessage = this.generateCommitMessage();
    console.log('\n📝 提交信息预览:');
    console.log('-'.repeat(50));
    console.log(defaultCommitMessage);
    console.log('-'.repeat(50));

    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });

    const answer = await new Promise(resolve => {
      rl.question('\n确认提交以上更改？(y/n/edit): ', resolve);
    });
    rl.close();

    if (answer.toLowerCase() === 'y') {
      this.workflowData.commitMessage = defaultCommitMessage;
      return this.doCommit();
    } else if (answer.toLowerCase() === 'edit') {
      const newMessage = await this.editCommitMessage(defaultCommitMessage);
      this.workflowData.commitMessage = newMessage;
      return this.doCommit();
    } else {
      console.log('❌ 提交已取消');
      return false;
    }
  }

  /**
   * 执行提交
   */
  doCommit() {
    try {
      console.log('\n📦 正在添加文件到 Git...');
      execSync('git add -A', { stdio: 'inherit' });

      console.log('\n💾 正在提交...');
      execSync(`git commit -m "${this.workflowData.commitMessage.replace(/"/g, '\\"')}"`, { 
        stdio: 'inherit' 
      });

      console.log('\n🚀 提交成功！');

      const pushAnswer = await new Promise(resolve => {
        const rl = readline.createInterface({
          input: process.stdin,
          output: process.stdout
        });
        rl.question('\n是否推送到远程仓库？(y/n): ', (answer) => {
          rl.close();
          resolve(answer);
        });
      });

      if (pushAnswer.toLowerCase() === 'y') {
        console.log('\n⬆️  正在推送...');
        execSync('git push', { stdio: 'inherit' });
        console.log('\n✅ 推送成功！');
      }

      return true;
    } catch (error) {
      console.error('❌ 提交失败:', error.message);
      return false;
    }
  }

  /**
   * 辅助方法
   */
  extractComponentName(requirement) {
    const match = requirement.match(/创建|新增|添加|实现|开发.*?(组件|页面|模块|功能)/i);
    if (match) {
      const words = requirement.split(/[，。、\s]+/);
      for (let i = 0; i < words.length; i++) {
        if (words[i].match(/组件|页面|模块|功能/)) {
          return words[i - 1] || 'NewComponent';
        }
      }
    }
    return null;
  }

  runCompileCheck() {
    try {
      const output = execSync('npm run compile-check-ts-native', { 
        encoding: 'utf8',
        stdio: 'pipe',
        timeout: 60000
      });
      return { success: true, output };
    } catch (error) {
      return { 
        success: false, 
        output: error.stdout || error.stderr || error.message 
      };
    }
  }

  generateCommitMessage() {
    const lines = this.workflowData.requirement.split('\n');
    const title = lines[0].slice(0, 50);
    const body = lines.slice(1).join('\n');

    let message = `feat: ${title}\n\n`;
    if (body) {
      message += `${body}\n\n`;
    }
    message += `流程: 需求输入 -> 开发 -> 错误检查 -> 测试 -> 确认提交`;

    return message;
  }

  async editCommitMessage(defaultMessage) {
    console.log('\n请输入新的提交信息（输入空行结束）:');
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });

    return new Promise((resolve) => {
      let message = '';
      const askNextLine = () => {
        rl.question('', (line) => {
          if (line.trim() === '') {
            rl.close();
            resolve(message || defaultMessage);
          } else {
            message += (message ? '\n' : '') + line;
            askNextLine();
          }
        });
      };
      askNextLine();
    });
  }

  /**
   * 运行完整流程
   */
  async run() {
    console.log('🚀 开始完整开发流程');
    console.log('='.repeat(50));

    try {
      // 阶段 1: 需求输入
      await this.inputRequirement();

      // 阶段 2: 开发实现
      const devSuccess = await this.develop();
      if (!devSuccess) {
        console.log('❌ 开发阶段失败');
        return;
      }

      // 阶段 3: 错误检查
      const checkSuccess = await this.checkErrors();
      if (!checkSuccess) {
        console.log('❌ 错误检查阶段失败');
        return;
      }

      // 阶段 4: 测试验证
      const testSuccess = await this.runTests();
      if (!testSuccess) {
        console.log('❌ 测试阶段失败');
        return;
      }

      // 阶段 5: 确认提交
      const commitSuccess = await this.confirmAndCommit();
      if (!commitSuccess) {
        console.log('❌ 提交阶段失败');
        return;
      }

      console.log('\n🎉 完整开发流程执行成功！');
      console.log('='.repeat(50));

    } catch (error) {
      console.error('\n❌ 流程执行出错:', error.message);
      console.error(error.stack);
    }
  }
}

// 命令行接口
if (require.main === module) {
  const workflow = new DevWorkflow();

  const args = process.argv.slice(2);
  if (args.includes('--help') || args.includes('-h')) {
    console.log(`
用法: node dev-workflow.js [选项]

选项:
  --help, -h     显示帮助信息
  --skip-tests    跳过测试阶段
  --skip-checks   跳过错误检查阶段
  --auto-commit   自动提交（使用默认提交信息）

示例:
  node dev-workflow.js
  node dev-workflow.js --skip-tests
  node dev-workflow.js --auto-commit
    `);
    process.exit(0);
  }

  workflow.run().catch(error => {
    console.error('Fatal error:', error);
    process.exit(1);
  });
}

module.exports = DevWorkflow;
"}

{"path":"dev-workflow.config.js","content":"/**
 * 开发工作流配置文件
 * 可以根据项目需求自定义各个阶段的行为
 */

module.exports = {
  // 项目信息
  project: {
    name: 'VSCode Saros Agents Client',
    version: '2.1.156942',
    rootDir: __dirname,
    srcDir: path.join(__dirname, 'src'),
    testDir: path.join(__dirname, 'test'),
    buildDir: path.join(__dirname, 'out')
  },

  // 阶段配置
  stages: {
    // 阶段 1: 需求输入
    requirement: {
      enabled: true,
      // 需求模板
      templates: [
        {
          name: '新功能开发',
          template: '功能描述: \n输入: \n输出: \n影响范围: '
        },
        {
          name: 'Bug 修复',
          template: '问题描述: \n复现步骤: \n预期行为: \n实际行为: '
        },
        {
          name: '性能优化',
          template: '优化目标: \n当前性能: \n预期提升: \n实施方案: '
        }
      ],
      // 是否启用 AI 辅助分析
      enableAIAnalysis: true
    },

    // 阶段 2: 开发实现
    development: {
      enabled: true,
      // 自动生成的文件类型
      generateTypes: ['component', 'service', 'test'],
      // 代码风格检查
      codeStyle: {
        indentSize: 2,
        semiColons: true,
        quoteMark: 'single',
        trailingComma: 'es5'
      },
      // 是否自动运行编译
      autoCompile: true,
      // 编译命令
      compileCommand: 'npm run compile-check-ts-native'
    },

    // 阶段 3: 错误检查
    errorCheck: {
      enabled: true,
      // 要执行的检查项
      checks: [
        {
          name: 'TypeScript 类型检查',
          command: 'npm run compile-check-ts-native',
          required: true,
          timeout: 120000 // 2分钟
        },
        {
          name: 'ESLint 检查',
          command: 'npm run eslint',
          required: true,
          timeout: 60000
        },
        {
          name: '代码格式检查',
          command: 'npm run hygiene',
          required: false,
          timeout: 30000
        },
        {
          name: '循环依赖检查',
          command: 'npm run check-cyclic-dependencies',
          required: false,
          timeout: 30000
        }
      ],
      // 自动修复配置
      autoFix: {
        eslint: true,
        format: true
      },
      // 错误处理策略: 'prompt' | 'auto-fix' | 'fail-fast'
      errorStrategy: 'prompt'
    },

    // 阶段 4: 测试验证
    testing: {
      enabled: true,
      // 测试类型配置
      testTypes: [
        {
          name: '单元测试',
          command: 'npm test -- --watchAll=false --coverage',
          required: true,
          timeout: 300000 // 5分钟
        },
        {
          name: '浏览器测试',
          command: 'npm run test-browser-no-install',
          required: false,
          timeout: 600000 // 10分钟
        },
        {
          name: 'E2E 测试',
          command: 'npm run test-extension',
          required: false,
          timeout: 600000
        }
      ],
      // 覆盖率要求
      coverage: {
        statements: 80,
        branches: 70,
        functions: 80,
        lines: 80
      },
      // 是否自动运行测试
      autoRun: true,
      // 测试失败策略: 'prompt' | 'continue' | 'fail-fast'
      failureStrategy: 'prompt'
    },

    // 阶段 5: 确认提交
    commit: {
      enabled: true,
      // 提交前检查
      preCommitChecks: [
        'git-status',
        'git-diff',
        'build-check'
      ],
      // 提交信息格式: 'conventional' | 'custom'
      messageFormat: 'conventional',
      // Conventional Commits 配置
      conventional: {
        types: ['feat', 'fix', 'docs', 'style', 'refactor', 'perf', 'test', 'chore'],
        scopes: ['ui', 'api', 'core', 'test', 'docs'],
        allowBreakingChanges: ['feat', 'fix']
      },
      // 是否自动推送到远程
      autoPush: false,
      // 推送前是否创建 Pull Request
      createPR: false
    }
  },

  // 通知配置
  notifications: {
    // 企业微信通知
    wecom: {
      enabled: false,
      webhook: process.env.WECOM_WEBHOOK || ''
    },
    // 钉钉通知
    dingtalk: {
      enabled: false,
      webhook: process.env.DINGTALK_WEBHOOK || ''
    },
    // 邮件通知
    email: {
      enabled: false,
      smtp: {
        host: '',
        port: 587,
        secure: false,
        auth: {
          user: '',
          pass: ''
        }
      },
      recipients: []
    }
  },

  // 日志配置
  logging: {
    level: 'info', // 'debug' | 'info' | 'warn' | 'error'
    file: 'dev-workflow.log',
    console: true,
    format: 'combined' // 'combined' | 'common' | 'dev' | 'short' | 'tiny'
  },

  // AI 辅助配置
  ai: {
    enabled: true,
    // 使用的 AI 模型
    model: 'claude-3.5-sonnet',
    // API 配置
    api: {
      provider: 'anthropic',
      apiKey: process.env.ANTHROPIC_API_KEY || '',
      baseURL: 'https://api.anthropic.com'
    },
    // 功能开关
    features: {
      codeGeneration: true,
      codeReview: true,
      testGeneration: true,
      commitMessageGeneration: true
    }
  },

  // 集成配置
  integrations: {
    // Jira 集成
    jira: {
      enabled: false,
      host: '',
      username: '',
      apiToken: '',
      projectKey: ''
    },
    // TAPD 集成
    tapd: {
      enabled: false,
      workspaceId: '',
      apiUser: '',
      apiPassword: ''
    },
    // 工蜂（Git）集成
    gongfeng: {
      enabled: false,
      apiURL: '',
      privateToken: ''
    }
  }
};

// 辅助函数：获取配置
function getConfig(stage, key) {
  if (stage && key) {
    return module.exports.stages[stage]?.[key];
  }
  return module.exports;
}

// 辅助函数：更新配置
function updateConfig(stage, key, value) {
  if (stage && key) {
    if (!module.exports.stages[stage]) {
      module.exports.stages[stage] = {};
    }
    module.exports.stages[stage][key] = value;
    return true;
  }
  return false;
}

module.exports.getConfig = getConfig;
module.exports.updateConfig = updateConfig;
"}

{"content":"#!/usr/bin/env node

/**
 * AI 辅助开发工作流
 * 集成 AI 能力到完整开发流程中
 */

const DevWorkflow = require('./dev-workflow.js');
const config = require('./dev-workflow.config.js');
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

class AIAssistedDevWorkflow extends DevWorkflow {
  constructor() {
    super();
    this.aiEnabled = config.ai.enabled;
    this.conversationHistory = [];
  }

  /**
   * 阶段 1: AI 辅助需求分析
   */
  async inputRequirement() {
    console.log('\n📝 阶段 1: 需求输入与 AI 分析');
    console.log('='.repeat(60));

    // 显示需求模板选择
    if (config.stages.requirement.templates.length > 0) {
      console.log('\n📋 可用需求模板:');
      config.stages.requirement.templates.forEach((template, index) => {
        console.log(`  ${index + 1}. ${template.name}`);
      });
      console.log('  0. 不使用模板');
    }

    const readline = require('readline');
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });

    // 获取用户选择
    const templateChoice = await new Promise(resolve => {
      rl.question('\n请选择模板 (输入编号, 回车跳过): ', resolve);
    });

    let requirement = '';
    if (templateChoice && parseInt(templateChoice) > 0) {
      const templateIndex = parseInt(templateChoice) - 1;
      if (config.stages.requirement.templates[templateIndex]) {
        requirement = config.stages.requirement.templates[templateIndex].template;
        console.log('\n已选择模板，请补充具体内容:');
        console.log('-'.repeat(60));
        console.log(requirement);
        console.log('-'.repeat(60));
      }
    }

    // 获取用户需求输入
    console.log('\n请输入您的需求 (输入空行结束):');
    requirement = await this.readMultilineInput(rl, requirement);
    rl.close();

    this.workflowData.requirement = requirement;

    // AI 分析需求
    if (this.aiEnabled && config.ai.features.codeGeneration) {
      console.log('\n🤖 AI 正在分析需求...');
      const analysis = await this.analyzeRequirementWithAI(requirement);

      console.log('\n📊 AI 需求分析结果:');
      console.log('='.repeat(60));
      console.log(`需求类型: ${analysis.type}`);
      console.log(`建议的实现方式: ${analysis.implementation}`);
      console.log(`预估影响文件: ${analysis.affectedFiles.join(', ')}`);
      console.log(`建议的测试策略: ${analysis.testStrategy}`);
      console.log('='.repeat(60));

      this.workflowData.aiAnalysis = analysis;
    }

    return true;
  }

  /**
   * 阶段 2: AI 辅助代码生成
   */
  async develop() {
    console.log('\n🔧 阶段 2: AI 辅助开发实现');
    console.log('='.repeat(60));

    if (!this.aiEnabled || !config.ai.features.codeGeneration) {
      console.log('⚠️  AI 辅助未启用，使用传统开发方式');
      return super.develop();
    }

    const requirement = this.workflowData.requirement;
    const analysis = this.workflowData.aiAnalysis;

    console.log('\n🤖 AI 正在生成代码...');

    try {
      // 根据需求生成代码
      const generatedCode = await this.generateCodeWithAI(requirement, analysis);

      // 显示生成的代码
      console.log('\n📄 AI 生成的代码:');
      console.log('='.repeat(60));
      generatedCode.forEach((file, index) => {
        console.log(`\n文件 ${index + 1}: ${file.path}`);
        console.log('-'.repeat(60));
        console.log(file.content);
        console.log('-'.repeat(60));
      });

      // 询问是否写入文件
      const readline = require('readline');
      const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout
      });

      const answer = await new Promise(resolve => {
        rl.question('\n是否将生成的代码写入文件？(y/n/edit): ', resolve);
      });

      if (answer.toLowerCase() === 'y') {
        // 写入文件
        for (const file of generatedCode) {
          const fullPath = path.join(__dirname, file.path);
          const dir = path.dirname(fullPath);

          // 创建目录
          if (!fs.existsSync(dir)) {
            fs.mkdirSync(dir, { recursive: true });
          }

          // 写入文件
          fs.writeFileSync(fullPath, file.content);
          console.log(`✅ 已写入: ${file.path}`);
          this.workflowData.filesChanged.push(file.path);
        }
      } else if (answer.toLowerCase() === 'edit') {
        // 允许用户编辑
        console.log('\n请手动编辑生成的代码...');
        // 这里可以打开编辑器
      }

      rl.close();

      // 运行初始编译检查
      console.log('\n🔍 执行初始编译检查...');
      const compileResult = this.runCompileCheck();

      if (compileResult.success) {
        console.log('✅ 初始编译检查通过');
      } else {
        console.log('⚠️  初始编译检查发现问题:');
        console.log(compileResult.output);

        // AI 辅助修复
        if (this.aiEnabled) {
          console.log('\n🤖 AI 正在尝试修复编译错误...');
          const fixed = await this.fixErrorsWithAI(compileResult.output);
          if (fixed) {
            console.log('✅ AI 已尝试修复，请检查代码');
          }
        }
      }

      return true;
    } catch (error) {
      console.error('❌ 代码生成失败:', error.message);
      return false;
    }
  }

  /**
   * 阶段 3: AI 辅助错误修复
   */
  async checkErrors() {
    console.log('\n🔍 阶段 3: 错误检查与 AI 辅助修复');
    console.log('='.repeat(60));

    const checks = config.stages.errorCheck.checks;
    let allPassed = true;

    for (const check of checks) {
      console.log(`\n正在执行: ${check.name}`);
      console.log('-'.repeat(60));

      try {
        const output = execSync(check.command, { 
          encoding: 'utf8',
          stdio: 'pipe',
          timeout: check.timeout
        });
        console.log(`✅ ${check.name} 通过`);
      } catch (error) {
        console.log(`❌ ${check.name} 失败`);
        const errorOutput = error.stdout || error.stderr || error.message;
        console.log('错误信息:');
        console.log(errorOutput);

        this.workflowData.errors.push({
          stage: check.name,
          error: errorOutput
        });

        // AI 辅助修复
        if (this.aiEnabled && config.ai.features.codeReview) {
          console.log('\n🤖 AI 正在分析错误并提供修复建议...');
          const fixSuggestion = await this.getFixSuggestionWithAI(errorOutput);

          console.log('\n💡 AI 修复建议:');
          console.log('='.repeat(60));
          console.log(fixSuggestion);
          console.log('='.repeat(60));

          const readline = require('readline');
          const rl = readline.createInterface({
            input: process.stdin,
            output: process.stdout
          });

          const answer = await new Promise(resolve => {
            rl.question('\n是否应用 AI 修复建议？(y/n): ', resolve);
          });
          rl.close();

          if (answer.toLowerCase() === 'y') {
            await this.applyFixWithAI(fixSuggestion);
            console.log('✅ 已应用修复，重新检查...');
            // 递归重新检查
            return this.checkErrors();
          }
        }

        if (check.required) {
          allPassed = false;
          if (config.stages.errorCheck.errorStrategy === 'fail-fast') {
            return false;
          }
        }
      }
    }

    if (allPassed) {
      console.log('\n✅ 所有错误检查通过！');
      return true;
    } else {
      console.log('\n⚠️  部分检查未通过');
      return false;
    }
  }

  /**
   * 阶段 4: AI 生成测试
   */
  async runTests() {
    console.log('\n🧪 阶段 4: 测试验证与 AI 生成测试');
    console.log('='.repeat(60));

    // AI 生成测试
    if (this.aiEnabled && config.ai.features.testGeneration) {
      console.log('\n🤖 AI 正在生成测试用例...');
      const generatedTests = await this.generateTestsWithAI(this.workflowData.filesChanged);

      if (generatedTests && generatedTests.length > 0) {
        console.log(`\n📝 AI 生成了 ${generatedTests.length} 个测试文件:`);
        generatedTests.forEach((test, index) => {
          console.log(`  ${index + 1}. ${test.path}`);
        });

        const readline = require('readline');
        const rl = readline.createInterface({
          input: process.stdin,
          output: process.stdout
        });

        const answer = await new Promise(resolve => {
          rl.question('\n是否写入测试文件？(y/n): ', resolve);
        });
        rl.close();

        if (answer.toLowerCase() === 'y') {
          for (const test of generatedTests) {
            const fullPath = path.join(__dirname, test.path);
            const dir = path.dirname(fullPath);

            if (!fs.existsSync(dir)) {
              fs.mkdirSync(dir, { recursive: true });
            }

            fs.writeFileSync(fullPath, test.content);
            console.log(`✅ 已写入测试: ${test.path}`);
          }
        }
      }
    }

    // 运行测试
    const testTypes = config.stages.testing.testTypes;
    let allPassed = true;

    for (const test of testTypes) {
      console.log(`\n正在执行: ${test.name}`);
      console.log('-'.repeat(60));

      try {
        const output = execSync(test.command, { 
          encoding: 'utf8',
          stdio: 'pipe',
          timeout: test.timeout
        });
        console.log(`✅ ${test.name} 通过`);

        // 显示覆盖率
        if (output.includes('coverage')) {
          console.log('\n📊 测试覆盖率:');
          console.log(this.extractCoverageInfo(output));
        }
      } catch (error) {
        console.log(`❌ ${test.name} 失败`);
        console.log('错误:', error.stdout || error.stderr || error.message);

        if (test.required) {
          allPassed = false;
          if (config.stages.testing.failureStrategy === 'fail-fast') {
            return false;
          }
        }
      }
    }

    if (allPassed) {
      console.log('\n✅ 所有测试通过！');
      return true;
    } else {
      console.log('\n⚠️  部分测试未通过');
      return false;
    }
  }

  /**
   * 阶段 5: AI 生成提交信息
   */
  async confirmAndCommit() {
    console.log('\n✅ 阶段 5: 确认提交');
    console.log('='.repeat(60));

    // 检查 Git 状态
    console.log('\n📊 Git 状态:');
    try {
      const status = execSync('git status --short', { encoding: 'utf8' });
      if (!status.trim()) {
        console.log('❌ 没有检测到任何更改');
        return false;
      }
      console.log(status);
    } catch (error) {
      console.error('❌ 无法获取 Git 状态');
      return false;
    }

    // AI 生成提交信息
    let commitMessage = '';
    if (this.aiEnabled && config.ai.features.commitMessageGeneration) {
      console.log('\n🤖 AI 正在生成提交信息...');
      commitMessage = await this.generateCommitMessageWithAI();

      console.log('\n📝 AI 生成的提交信息:');
      console.log('='.repeat(60));
      console.log(commitMessage);
      console.log('='.repeat(60));
    } else {
      commitMessage = this.generateCommitMessage();
    }

    const readline = require('readline');
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout
    });

    const answer = await new Promise(resolve => {
      rl.question('\n确认提交以上更改？(y/n/edit): ', resolve);
    });
    rl.close();

    if (answer.toLowerCase() === 'y') {
      this.workflowData.commitMessage = commitMessage;
      return this.doCommit();
    } else if (answer.toLowerCase() === 'edit') {
      const newMessage = await this.editCommitMessage(commitMessage);
      this.workflowData.commitMessage = newMessage;
      return this.doCommit();
    } else {
      console.log('❌ 提交已取消');
      return false;
    }
  }

  /**
   * AI 辅助方法
   */
  async analyzeRequirementWithAI(requirement) {
    // 这里是模拟 AI 分析，实际应该调用 AI API
    // 例如：Anthropic Claude API, OpenAI API 等

    console.log('  [模拟] 调用 AI API 分析需求...');

    // 模拟返回结果
    return {
      type: '新功能开发',
      implementation: '建议创建新的 React 组件，并集成到现有页面中',
      affectedFiles: ['src/components/NewComponent.tsx', 'src/pages/MainPage.tsx', 'src/App.tsx'],
      testStrategy: '单元测试 + 组件测试 + E2E 测试'
    };
  }

  async generateCodeWithAI(requirement, analysis) {
    // 模拟 AI 代码生成
    console.log('  [模拟] 调用 AI API 生成代码...');

    // 模拟返回结果
    return [
      {
        path: 'src/components/ExampleComponent.tsx',
        content: `import React from 'react';
import { Button, Input } from '@/components/ui';

