      createPR: false
    }
  },

  // 通知配置
  notifications: {
    // 企业微信通知
    wecom: {
      enabled: false,
      webhook: process.env.WECOM_WEBHOOK || ''
    },
    // 钉钉通知
    dingtalk: {
      enabled: false,
      webhook: process.env.DINGTALK_WEBHOOK || ''
    },
    // 邮件通知
    email: {
      enabled: false,
      smtp: {
        host: '',
        port: 587,
        secure: false,
        auth: {
          user: '',
          pass: ''
        }
      },
      recipients: []
    }
  },

  // 日志配置
  logging: {
    level: 'info', // 'debug' | 'info' | 'warn' | 'error'
    file: 'dev-workflow.log',
    console: true,
    format: 'combined' // 'combined' | 'common' | 'dev' | 'short' | 'tiny'
  },

  // AI 辅助配置
  ai: {
    enabled: true,
    // 使用的 AI 模型
    model: 'claude-3.5-sonnet',
    // API 配置
    api: {
      provider: 'anthropic',
      apiKey: process.env.ANTHROPIC_API_KEY || '',
      baseURL: 'https://api.anthropic.com'
    },
    // 功能开关
    features: {
      codeGeneration: true,
      codeReview: true,
      testGeneration: true,
      commitMessageGeneration: true
    }
  },

  // 集成配置
  integrations: {
    // Jira 集成
    jira: {
      enabled: false,
      host: '',
      username: '',
      apiToken: '',
      projectKey: ''
    },
    // TAPD 集成
    tapd: {
      enabled: false,
      workspaceId: '',
      apiUser: '',
      apiPassword: ''
    },
    // 工蜂（Git）集成
    gongfeng: {
      enabled: false,
      apiURL: '',
      privateToken: ''
    }
  }
};

// 辅助函数：获取配置
function getConfig(stage, key) {
  if (stage && key) {
    return module.exports.stages[stage]?.[key];
  }
  return module.exports;
}

// 辅助函数：更新配置
function updateConfig(stage, key, value) {
  if (stage && key) {
    if (!module.exports.stages[stage]) {
      module.exports.stages[stage] = {};
    }
    module.exports.stages[stage][key] = value;
    return true;
  }
  return false;
}

module.exports.getConfig = getConfig;
module.exports.updateConfig = updateConfig;
