    console.log('='.repeat(60));

    // 显示需求模板选择
    if (config.stages.requirement.templates.length > 0) {
      console.log('\n📋 可用需求模板:');
      config.stages.requirement.templates.forEach((template, index) => {
        console.log(`  ${index + 1}. ${template.name}`);
      });
